const item = $input.first().json;
const employeeName = `${item.first_name} ${item.last_name}`;
const years = item.years_of_service || 0;
const notifications = [];

if (item.employee_email) {
  notifications.push({
    to: item.employee_email,
    kind: 'employee',
    employee_id: item.id,
    employee_name: employeeName,
    years
  });
}

if (item.manager_email) {
  notifications.push({
    to: item.manager_email,
    kind: 'manager',
    employee_id: item.id,
    employee_name: employeeName,
    years
  });
}

return notifications.map((notification) => ({ json: notification }));
